fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    let vlen = values.len();
    a.into_iter()
     .zip(mask.into_iter())
     .enumerate()
     .map(|(i, (aval, m))| {
         if m {
             // pick from values cyclically
             values[i % vlen]
         } else {
             // keep original
             aval
         }
     })
     .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_putmask_basic() {
        let a = vec![1.0, 2.0, 3.0, 4.0];
        let mask = vec![false, true, true, false];
        let values = vec![10.0, 20.0];
        let res = putmask(a, mask, values);
        // masked positions: 1→values[1%2]=20.0, 2→values[2%2]=10.0
        assert_eq!(res, vec![1.0, 20.0, 10.0, 4.0]);
    }

    #[test]
    fn test_putmask_all_masked() {
        let a = vec![5.0, 6.0, 7.0];
        let mask = vec![true, true, true];
        let values = vec![1.1];
        let res = putmask(a, mask, values);
        // all replaced by values[ i % 1 ] == values[0]
        assert_eq!(res, vec![1.1, 1.1, 1.1]);
    }

    #[test]
    fn test_putmask_none_masked() {
        let a = vec![8.0, 9.0];
        let mask = vec![false, false];
        let values = vec![0.0];
        let res = putmask(a, mask, values);
        // no changes
        assert_eq!(res, vec![8.0, 9.0]);
    }
}